"""Cuaderno del estudiante, 3.º medio Lengua y Literatura FG, OAC 07 (recursos lingüísticos y multimodales en la producción).

Todos los textos y casos son originales e inventados («de ejemplo»); cada ejercicio trae escritos los datos que necesita.
No hay audio, video ni imágenes reales: los recursos visuales y sonoros se describen con palabras.
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from fg_leli_common import L, E, arith  # noqa: E402,F401

OA = "FG-LELI-3M-OAC-07"


def AB(q, right, wrong, why):
    """Pregunta de dos alternativas; la correcta se escribe primero y el registro la reubica."""
    return E(f"{q} A) {right} B) {wrong}", f"A) {right}", why)


